def squash(s: str) -> str:
    out = []
    n = len(s)
    i = 0

    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1

        run = j - i

        if c == '\\' or '0' <= c <= '9':
            escaped = '\\' + c
        else:
            escaped = c

        if run >= 3:
            out.append(str(run) + escaped)
        else:
            out.append(escaped * run)

        i = j

    return ''.join(out)
